import{c as s,Q as a,j as i,m as t}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"Setting up the WiFi TCP bridge","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tcp-bridge.md","filePath":"docs/tcp-bridge.md"}'),n={name:"docs/tcp-bridge.md"};function r(o,e,p,h,l,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="setting-up-the-wifi-tcp-bridge" tabindex="-1">Setting up the WiFi TCP bridge <a class="header-anchor" href="#setting-up-the-wifi-tcp-bridge" aria-label="Permalink to &quot;Setting up the WiFi TCP bridge&quot;">​</a></h1><p>This guide is for a repeater flashed with the <code>_bridge_tcp</code> firmware. The bridge links two or more LoRa networks through a central TCP server.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>An ESP32 repeater with WiFi and <code>_bridge_tcp</code> firmware.</li><li>The repeater USB port, for example <code>/dev/ttyACM0</code>.</li><li><code>meshcli</code> installed on your computer.</li><li>A TCP bridge server reachable by the repeater.</li></ul><h2 id="_1-start-the-tcp-bridge-server" tabindex="-1">1. Start the TCP bridge server <a class="header-anchor" href="#_1-start-the-tcp-bridge-server" aria-label="Permalink to &quot;1. Start the TCP bridge server&quot;">​</a></h2><p>Start the server on a machine that the bridge repeaters can reach. This can be a VPS, Raspberry Pi, or local computer.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span></span></code></pre></div><p>For monitoring during testing, start it with status and heartbeat timeouts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status-interval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-packets</span></span></code></pre></div><p>TCP bridge firmware sends a heartbeat to the server every 30 seconds. The server uses normal packets and heartbeats to update the client&#39;s <code>idle</code> timer. If a node loses power and no heartbeat arrives before <code>--client-timeout</code>, the server disconnects that stale node.</p><p>For local testing, use this machine&#39;s LAN IP address as <code>bridge.server</code>. For internet use, use a public IP address or domain name.</p><h2 id="_2-connect-to-the-repeater" tabindex="-1">2. Connect to the repeater <a class="header-anchor" href="#_2-connect-to-the-repeater" aria-label="Permalink to &quot;2. Connect to the repeater&quot;">​</a></h2><p>A TCP bridge build is a repeater, not a serial companion. Use <code>-r</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meshcli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span></code></pre></div><p>If you see this error:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No response from meshcore node, disconnecting</span></span>
<span class="line"><span>Are you sure your node is a serial companion ?</span></span>
<span class="line"><span>To connect to a repeater, use -r option.</span></span></code></pre></div><p>then <code>-r</code> was missing. Start again with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meshcli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span></code></pre></div><h2 id="_3-configure-wifi-and-the-tcp-bridge" tabindex="-1">3. Configure WiFi and the TCP bridge <a class="header-anchor" href="#_3-configure-wifi-and-the-tcp-bridge" aria-label="Permalink to &quot;3. Configure WiFi and the TCP bridge&quot;">​</a></h2><p>Run these commands through <code>meshcli</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.enabled off</span></span>
<span class="line"><span>set wifi.ssid MyWiFiName</span></span>
<span class="line"><span>set wifi.password MyWiFiPassword</span></span>
<span class="line"><span>set bridge.server 192.168.1.123</span></span>
<span class="line"><span>set bridge.port 4200</span></span></code></pre></div><p>Replace <code>192.168.1.123</code> with the IP address or hostname of your TCP bridge server.</p><p>For a server on the internet:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.server myserver.example.com</span></span></code></pre></div><h2 id="_4-reboot-after-wifi-changes" tabindex="-1">4. Reboot after WiFi changes <a class="header-anchor" href="#_4-reboot-after-wifi-changes" aria-label="Permalink to &quot;4. Reboot after WiFi changes&quot;">​</a></h2><p>After <code>set wifi.ssid</code> and <code>set wifi.password</code>, reboot the repeater before the WiFi settings take effect.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot</span></span></code></pre></div><p>Then connect again:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meshcli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span></code></pre></div><p>Enable the bridge after reconnecting:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.enabled on</span></span></code></pre></div><h2 id="_5-check-the-settings" tabindex="-1">5. Check the settings <a class="header-anchor" href="#_5-check-the-settings" aria-label="Permalink to &quot;5. Check the settings&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get bridge.type</span></span>
<span class="line"><span>get wifi.ssid</span></span>
<span class="line"><span>get bridge.server</span></span>
<span class="line"><span>get bridge.port</span></span>
<span class="line"><span>get bridge.enabled</span></span></code></pre></div><p>Expected bridge type:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; tcp</span></span></code></pre></div><p><code>get wifi.password</code> does not show the real password. It returns <code>***</code>.</p><h2 id="_6-link-multiple-repeaters" tabindex="-1">6. Link multiple repeaters <a class="header-anchor" href="#_6-link-multiple-repeaters" aria-label="Permalink to &quot;6. Link multiple repeaters&quot;">​</a></h2><p>Flash a repeater at each location with <code>_bridge_tcp</code> firmware and configure all of them to use the same TCP server and port:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.server myserver.example.com</span></span>
<span class="line"><span>set bridge.port 4200</span></span>
<span class="line"><span>set bridge.enabled on</span></span></code></pre></div><p>Packets received over LoRa by one repeater are sent over TCP to the server and injected back into the local LoRa network by the other repeater.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="permission-denied-on-dev-ttyacm0" tabindex="-1">Permission denied on <code>/dev/ttyACM0</code> <a class="header-anchor" href="#permission-denied-on-dev-ttyacm0" aria-label="Permalink to &quot;Permission denied on \`/dev/ttyACM0\`&quot;">​</a></h3><p>Add your user to the <code>dialout</code> group:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dialout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span></code></pre></div><p>Log out and back in afterwards.</p><h3 id="wrong-serial-port" tabindex="-1">Wrong serial port <a class="header-anchor" href="#wrong-serial-port" aria-label="Permalink to &quot;Wrong serial port&quot;">​</a></h3><p>Check which port appears after plugging in the repeater:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span></code></pre></div><p>Then use the right port with <code>meshcli -s &lt;port&gt; -r</code>.</p><h3 id="bridge-does-not-come-online" tabindex="-1">Bridge does not come online <a class="header-anchor" href="#bridge-does-not-come-online" aria-label="Permalink to &quot;Bridge does not come online&quot;">​</a></h3><p>Check:</p><ul><li>If the CLI becomes slow or noisy while configuring, run <code>set bridge.enabled off</code>, reboot, then configure WiFi and server settings before enabling it again.</li><li>The repeater was rebooted after setting WiFi.</li><li><code>get bridge.enabled</code> returns <code>on</code>.</li><li><code>get bridge.server</code> and <code>get bridge.port</code> are correct.</li><li>The TCP bridge server is running.</li><li>The server is reachable from the same WiFi network or over the internet.</li><li>A firewall allows TCP port <code>4200</code>.</li></ul><h3 id="server-still-shows-a-node-after-power-is-removed" tabindex="-1">Server still shows a node after power is removed <a class="header-anchor" href="#server-still-shows-a-node-after-power-is-removed" aria-label="Permalink to &quot;Server still shows a node after power is removed&quot;">​</a></h3><p>Use the heartbeat-aware timeout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status-interval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span></span></code></pre></div><p>The status line shows <code>idle</code>, <code>hb_age</code>, and <code>hb</code>. If <code>idle</code> grows beyond <code>--client-timeout</code>, the server disconnects the stale TCP session.</p><p>For single-node-per-IP LAN testing you can also use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replace-same-ip</span></span></code></pre></div><p>Do not use <code>--replace-same-ip</code> when multiple bridge nodes may connect from the same public IP or NAT.</p><h3 id="the-tcp-bridge-is-not-encrypted" tabindex="-1">The TCP bridge is not encrypted <a class="header-anchor" href="#the-tcp-bridge-is-not-encrypted" aria-label="Permalink to &quot;The TCP bridge is not encrypted&quot;">​</a></h3><p>The current TCP bridge does not use TLS. Use it on a trusted network or restrict access to the server with firewall rules.</p>`,61)])])}const k=s(n,[["render",r]]);export{g as __pageData,k as default};
